"""Write firmware/include/probepen_pins.h from the GPIO dictionary in hw/design.py.

    python -m hw.tools.gen_pins_h
"""
from pathlib import Path

from hw import design

DST = Path(__file__).resolve().parents[2] / "firmware" / "include" / "probepen_pins.h"


def main():
    order = sorted(design.GPIO.items(), key=lambda kv: kv[1])
    width = max(len(k) for k, _ in order) + 5
    out = [
        "#ifndef PROBEPEN_PINS_H", "#define PROBEPEN_PINS_H", "",
        "/* Generated by hw/tools/gen_pins_h.py from the GPIO dictionary in hw/design.py (RP2354B, QFN-80).",
        " * AD9288 channel A is on GPIO16..23 (bit-reversed: D7A on GPIO16) and channel B on GPIO32..39,",
        " * so one PIO block with GPIOBASE = 16 reads both channels in a single 32-bit `in pins`.",
        " */", "",
    ]
    out += [f"#define {('PIN_' + k).ljust(width)} {v}u" for k, v in order]
    out += ["", "#endif /* PROBEPEN_PINS_H */", ""]
    DST.write_text("\n".join(out), encoding="utf8", newline="\n")
    print("wrote", DST)


if __name__ == "__main__":
    main()
